import { useTranslation } from "@/lib/i18n";
import type { DifficultyLabel } from "@/lib/platformTypes";

const CLASS_BY_BAND: Record<string, string> = {
  easy: "badge ok",
  moderate: "badge",
  hard: "badge warn",
  unsolved: "badge danger",
};

